const checksum = (ring) => ring.reduce((s, [x, y]) => s + x * 7 + y * 13, 0);

function replaceRegion(entities, id, years, rid, ring, name) {
  const ent = entities.find((x) => x.id === id);
  if (!ent) throw new Error(`pakistan fixes: no entity ${id}`);
  for (const year of years) {
    const kf = ent.overlays.find((o) => o.year === year);
    const i = kf ? kf.regions.findIndex((r) => (typeof r === 'string' ? r : r.id) === rid) : -1;
    if (i < 0) throw new Error(`pakistan fixes: ${id} ${year} has no ${rid}`);
    kf.regions[i] = { id: rid, name, ring: ensureClockwise(ring) };
  }
}

/** Apply `pakistanShapeFixes` (runs after the Greece fixes; throws if a target is missing). */
export function applyPakistanShapeFixes(entities) {
  const shahis = entities.find((x) => x.id === 'kabul-shahis');
  const years = shahis ? shahis.overlays.filter((o) => o.regions.some((r) => (typeof r === 'string' ? r : r.id) === 'punjab')).map((o) => o.year) : [];
  if (years.join() !== '1001,1013,1014,1019,1020') throw new Error(`pakistan fixes: kabul-shahis punjab keyframes changed (${years.join()})`);
  replaceRegion(entities, 'kabul-shahis', years, 'punjab', PK_PIECES.N_PUNJAB, 'The northern Punjab (the Salt Range, Nandana, Lahore)');
  for (const [id, { region, rings }] of Object.entries(PK_TRIMS)) {
    const ent = entities.find((x) => x.id === id);
    if (!ent) throw new Error(`pakistan fixes: no entity ${id}`);
    for (const [y, { sum, ring }] of Object.entries(rings)) {
      const kf = ent.overlays.find((o) => o.year === Number(y));
      const r = kf?.regions.find((q) => typeof q !== 'string' && q.id === region);
      if (!r?.ring || Math.abs(checksum(r.ring) - sum) > 1e-6) throw new Error(`pakistan fixes: ${id} ${region} ${y} changed — regenerate the trim`);
      r.ring = ensureClockwise(ring);
    }
  }
}

